(function(){
if(typeof window.loadCloudData!=='function'||window.__legacyMigrationInstalled)return;
window.__legacyMigrationInstalled=true;
const originalLoadCloudData=window.loadCloudData;
window.loadCloudData=async function(){
if(window.__legacyMigrationDone)return originalLoadCloudData();
if(!window.cloudClient||!window.cloudUser)return originalLoadCloudData();
const q=await window.cloudClient.from('transactions').select('id',{count:'exact',head:true});
if(q.error)return originalLoadCloudData();
if((q.count||0)>0){window.__legacyMigrationDone=true;return originalLoadCloudData();}
const p=await window.cloudClient.from('projects').select('id,name,client,agreed_value');
if(p.error)return originalLoadCloudData();
const byName={};for(const p0 of (p.data||[]))byName[p0.name]=p0.id;
for(const p0 of window.legacyBackup.projects){if(!byName[p0.name]){const ins=await window.cloudClient.from('projects').insert({name:p0.name,client:p0.client||'',agreed_value:+p0.value||0}).select('id,name').single();if(ins.error){alert('Migration stopped while creating projects: '+ins.error.message);return originalLoadCloudData();}byName[p0.name]=ins.data.id;}}
const rows=window.legacyBackup.tx.map(x=>({transaction_date:x.date||null,type:x.type,amount:+x.amount||0,party:x.party||null,project_id:byName[x.project]||null,category:x.category||'Other',description:(x.description||'')+(x.mode==='Cash - Home'?' | Cash - Home':''),payment_mode:x.mode==='Cash - Home'?'Cash':x.mode,cheque_status:x.mode==='Cheque'?(x.chequeStatus||'Pending'):null}));
for(let i=0;i<rows.length;i+=100){const ins=await window.cloudClient.from('transactions').insert(rows.slice(i,i+100));if(ins.error){alert('Migration stopped while saving transactions: '+ins.error.message);return originalLoadCloudData();}}
const ob=await window.cloudClient.from('opening_balances').upsert({bank_balance:+window.legacyBackup.opening.bank||0,cash_balance:+window.legacyBackup.opening.cash||0},{onConflict:'user_id'});if(ob.error){alert('Migration stopped while saving starting money: '+ob.error.message);return originalLoadCloudData();}
window.__legacyMigrationDone=true;await originalLoadCloudData();alert('Your existing accounting data has been moved to your private cloud account successfully. '+rows.length+' transactions are now stored in Supabase.');
};
})();
